//! Plain words. Every sentence here is built from a computed fact and carries the
//! factors and rule ids it came from, so the app can always show "why" beside "what".
//! Nothing is generated by a language model; the templates are in this file.

#![forbid(unsafe_code)]

pub mod glossary;

use kshana_chart::Chart;
use kshana_ephem::Spk;
use kshana_forecast::{life_map, sade_sati, transits_at, TransitKind};
use kshana_rules::{
    agreeing_levels, assess, promise, timing, yogas, Ashtakoota, Facts, MangalDosha,
    SynastryAspect, AREAS,
};
use kshana_time::{Instant, Utc};
use kshana_vedic::panchanga::NAKSHATRA_NAMES;
use kshana_vedic::{chara_karakas, nakshatra, naming_for, Ayanamsa, DashaLord};

pub use glossary::{glossary, GlossaryEntry};

/// One sentence with its evidence.
#[derive(Clone, Debug, PartialEq)]
pub struct Sentence {
    /// The sentence.
    pub text: String,
    /// The factors behind it, in words.
    pub why: Vec<String>,
    /// How firmly the engine holds it, `[0, 1]`.
    pub confidence: f64,
    /// Rule ids cited.
    pub rules: Vec<String>,
}

/// A titled group of sentences.
#[derive(Clone, Debug, PartialEq)]
pub struct Section {
    /// Title.
    pub title: String,
    /// One-line summary.
    pub summary: String,
    /// Sentences.
    pub sentences: Vec<Sentence>,
}

/// Sign names, sidereal or tropical index 0–11.
pub const SIGN_NAMES: [&str; 12] = [
    "Aries",
    "Taurus",
    "Gemini",
    "Cancer",
    "Leo",
    "Virgo",
    "Libra",
    "Scorpio",
    "Sagittarius",
    "Capricorn",
    "Aquarius",
    "Pisces",
];

const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

/// "12 Mar 2027" for an instant (UTC date).
pub fn date_words(i: Instant) -> String {
    let u = Utc::from_instant(i);
    format!(
        "{} {} {}",
        u.day,
        MONTHS[(u.month as usize).clamp(1, 12) - 1],
        u.year
    )
}

/// "Mar 2027".
pub fn month_words(i: Instant) -> String {
    let u = Utc::from_instant(i);
    format!("{} {}", MONTHS[(u.month as usize).clamp(1, 12) - 1], u.year)
}

/// The graha's everyday name.
pub fn graha_words(g: DashaLord) -> &'static str {
    match g {
        DashaLord::Sun => "the Sun",
        DashaLord::Moon => "the Moon",
        DashaLord::Mars => "Mars",
        DashaLord::Mercury => "Mercury",
        DashaLord::Jupiter => "Jupiter",
        DashaLord::Venus => "Venus",
        DashaLord::Saturn => "Saturn",
        DashaLord::Rahu => "Rahu",
        DashaLord::Ketu => "Ketu",
    }
}

fn area_words(name: &str) -> &'static str {
    match name {
        "Career" => "your work and standing",
        "Marriage" => "marriage and partnership",
        "Children" => "children",
        "Wealth" => "money and gains",
        "Health" => "health and vitality",
        "Property" => "home and property",
        "Education" => "learning",
        "Foreign" => "travel and life abroad",
        _ => "this matter",
    }
}

fn s(text: String, why: Vec<String>, confidence: f64, rules: Vec<String>) -> Sentence {
    Sentence {
        text,
        why,
        confidence: confidence.clamp(0.0, 1.0),
        rules,
    }
}

/// Who the person is: lagna, Moon, Sun, the soul planet, the naming syllable.
pub fn who(natal: &Chart) -> Section {
    let facts = Facts::from_chart(natal);
    let moon = &facts.planets[1];
    let sun = &facts.planets[0];
    let nk = nakshatra(moon.sidereal);
    let (nname, pada, syl) = naming_for(moon.sidereal);
    let sid: [f64; 7] = std::array::from_fn(|i| facts.planets[i].sidereal);
    let kk = chara_karakas(sid);
    let mut sentences = vec![
        s(
            format!(
                "You rise with {} on the eastern horizon. That is the lens your whole chart is read through.",
                SIGN_NAMES[facts.lagna_sign as usize]
            ),
            vec![format!(
                "Lagna (sidereal) {:.2}° = {}",
                facts.cusps[0], SIGN_NAMES[facts.lagna_sign as usize]
            )],
            1.0,
            vec![],
        ),
        s(
            format!(
                "Your Moon is in {}, in the star {} (pada {}). The Moon is your mind; its star sets your first dasha and your naming syllable, {}.",
                SIGN_NAMES[moon.sign as usize], nname, pada, syl
            ),
            vec![format!(
                "Moon sidereal {:.4}°, nakshatra {} fraction {:.3}",
                moon.sidereal,
                NAKSHATRA_NAMES[nk.index],
                nk.fraction
            )],
            1.0,
            vec![],
        ),
        s(
            format!(
                "Your Sun is in {} (sidereal). In the Western zodiac that is {}.",
                SIGN_NAMES[sun.sign as usize],
                SIGN_NAMES[(natal.bodies[0].tropical / 30.0).floor() as usize % 12]
            ),
            vec![format!(
                "Sun sidereal {:.4}°, tropical {:.4}°, ayanamsa {:.4}°",
                sun.sidereal, natal.bodies[0].tropical, natal.ayanamsa_deg
            )],
            1.0,
            vec![],
        ),
        s(
            format!(
                "{} is your Atmakaraka, the planet with the highest degree in its sign: {}.",
                capital(graha_words(kk[0].graha)),
                kshana_vedic::KARAKA_MEANINGS[0]
            ),
            vec![format!(
                "{:?} at {:.2}° in its sign; Darakaraka (spouse) is {:?}",
                kk[0].graha, kk[0].degree_in_sign, kk[6].graha
            )],
            1.0,
            vec!["Jaimini chara karaka, 7-planet scheme".to_string()],
        ),
    ];
    for y in yogas(&facts) {
        sentences.push(s(
            format!("{} is present in your chart.", y.name),
            y.hit.factors.clone(),
            y.hit.weight,
            vec![y.hit.rule_id.to_string()],
        ));
    }
    Section {
        summary: format!(
            "{} rising, Moon in {} ({})",
            SIGN_NAMES[facts.lagna_sign as usize], SIGN_NAMES[moon.sign as usize], nname
        ),
        title: "Who you are".to_string(),
        sentences,
    }
}

fn capital(w: &str) -> String {
    let mut c = w.chars();
    match c.next() {
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
        None => String::new(),
    }
}

/// One life area, in words: promise, strength, and the tightest supported window now.
pub fn area_section(natal: &Chart, area: kshana_rules::Area, at: Instant) -> Section {
    let facts = Facts::from_chart(natal);
    let p = promise(&facts, area);
    let a = assess(&facts, area);
    let funnel = timing(&facts, area, natal.bodies[1].sidereal, natal.instant, at, 5);
    let agree = agreeing_levels(&funnel);
    let words = area_words(area.name);
    let mut sentences = Vec::new();
    let verdict = match (p.promised, a.score >= 0.5) {
        (true, true) => format!(
            "Both traditions agree: {} is promised in this chart, and the chart supports it.",
            words
        ),
        (true, false) => format!(
            "The KP sub-lord promises {}, but the Parashari reading finds the house weak. Expect it, with effort.",
            words
        ),
        (false, true) => format!(
            "The Parashari reading supports {}, but the KP sub-lord does not promise it outright. Expect delays or conditions.",
            words
        ),
        (false, false) => format!(
            "Neither tradition promises {} freely in this chart. It is not denied; it must be earned and timed.",
            words
        ),
    };
    let conf = 0.5
        + 0.5
            * (p.strength - 0.5).abs().min(0.5)
            * if p.promised == (a.score >= 0.5) {
                2.0
            } else {
                1.0
            };
    sentences.push(s(
        verdict,
        p.hit
            .factors
            .iter()
            .cloned()
            .chain(a.hits.iter().flat_map(|h| h.factors.clone()))
            .collect(),
        conf,
        std::iter::once(p.hit.rule_id.to_string())
            .chain(a.hits.iter().map(|h| h.rule_id.to_string()))
            .collect(),
    ));
    sentences.push(s(
        format!(
            "The sub-lord of your {} cusp is {}; the lord of the house is {} with a Parashari strength of {:.0} out of 100.",
            ordinal(area.primary),
            graha_words(p.sub_lord),
            graha_words(a.lord),
            a.score * 100.0
        ),
        vec![format!("KP strength {:.2}, Parashari score {:.2}", p.strength, a.score)],
        1.0,
        vec![],
    ));
    if let Some(top) = funnel.first() {
        let running = format!(
            "You are in the {} mahadasha ({} to {}).",
            graha_words(top.period.lord),
            month_words(top.period.start),
            month_words(top.period.end)
        );
        sentences.push(s(running, vec![], 1.0, vec![]));
    }
    if agree > 0 {
        let deep = &funnel[agree - 1];
        sentences.push(s(
            format!(
                "The running periods support {} down to level {} of 5: from {} to {}, {}'s period carries it.",
                words,
                agree,
                date_words(deep.period.start),
                date_words(deep.period.end),
                graha_words(deep.period.lord)
            ),
            deep.supports
                .iter()
                .map(|x| format!("{:?} signifies house {} ({:?})", deep.period.lord, x.house, x.level))
                .collect(),
            0.4 + 0.12 * agree as f64,
            vec!["KS-K-0002".to_string()],
        ));
    } else {
        sentences.push(s(
            format!(
                "The running mahadasha does not signify {} just now. Nothing is lost; the next supporting period is the one to prepare for.",
                words
            ),
            vec![],
            0.6,
            vec!["KS-K-0002".to_string()],
        ));
    }
    Section {
        title: area.name.to_string(),
        summary: if p.promised {
            "promised".to_string()
        } else {
            "to be earned".to_string()
        },
        sentences,
    }
}

fn ordinal(n: u8) -> String {
    let suf = match n {
        1 => "st",
        2 => "nd",
        3 => "rd",
        _ => "th",
    };
    format!("{n}{suf}")
}

/// What the sky is doing to the chart now: Sade Sati, Jupiter and Saturn transits.
pub fn now_section(spk: &Spk, natal: &Chart, at: Instant, ayanamsa: Ayanamsa) -> Section {
    let mut sentences = Vec::new();
    let mut summary = String::new();
    if let Ok(ss) = sade_sati(spk, natal, at, ayanamsa) {
        let phase_words = match ss.phase {
            1 => Some("the first phase of Sade Sati: Saturn is in the sign before your Moon"),
            2 => Some("the peak of Sade Sati: Saturn is over your Moon"),
            3 => Some("the last phase of Sade Sati: Saturn is in the sign after your Moon"),
            _ => None,
        };
        match phase_words {
            Some(w) => {
                let until = ss
                    .phase_end
                    .map(|e| format!(" It ends on {}.", date_words(e)))
                    .unwrap_or_default();
                summary = "Sade Sati running".to_string();
                sentences.push(s(
                    format!("You are in {}.{} The classical reading is a time of effort, slowing and clearing, not of punishment.", w, until),
                    vec![format!(
                        "Saturn sidereal sign {}, natal Moon sign {}",
                        SIGN_NAMES[ss.saturn_sign as usize], SIGN_NAMES[ss.moon_sign as usize]
                    )],
                    0.9,
                    vec!["Gochara: Sade Sati".to_string()],
                ));
            }
            None => {
                if let Some(n) = ss.next_start {
                    sentences.push(s(
                        format!(
                            "You are not in Sade Sati. The next one begins on {}.",
                            date_words(n)
                        ),
                        vec![format!(
                            "Saturn in {}, Moon in {}",
                            SIGN_NAMES[ss.saturn_sign as usize], SIGN_NAMES[ss.moon_sign as usize]
                        )],
                        0.95,
                        vec!["Gochara: Sade Sati".to_string()],
                    ));
                }
            }
        }
    }
    if let Ok(ts) = transits_at(spk, natal, at, ayanamsa) {
        for t in ts.iter().filter(|t| matches!(t.body, "Jupiter" | "Saturn")) {
            let text = match t.kind {
                TransitKind::FromMoon => {
                    let good = match (t.body, t.house) {
                        ("Jupiter", 2 | 5 | 7 | 9 | 11) => "favourable",
                        ("Saturn", 3 | 6 | 11) => "favourable",
                        _ => "demanding",
                    };
                    format!(
                        "{} is passing through your {} house from the Moon, a {} transit by the classical table.",
                        t.body,
                        ordinal(t.house),
                        good
                    )
                }
                TransitKind::OverNatal => format!(
                    "{} is passing over your natal {} ({:.1}° apart).",
                    t.body, t.natal, t.separation
                ),
                TransitKind::AspectingNatal => {
                    format!("{} aspects your natal {} by sign.", t.body, t.natal)
                }
            };
            sentences.push(s(
                text,
                vec![format!("{} sidereal {:.3}°", t.body, t.longitude)],
                0.8,
                vec!["Gochara".to_string()],
            ));
        }
    }
    if summary.is_empty() {
        summary = format!("{} transits in force", sentences.len());
    }
    Section {
        title: "Right now".to_string(),
        summary,
        sentences,
    }
}

/// The years ahead in words: the best and hardest stretches per area over `years`.
pub fn years_ahead(natal: &Chart, at: Instant, years: u32) -> Section {
    let rows = life_map(natal, 100);
    let current_age = rows.iter().rposition(|r| r.start <= at).unwrap_or(0);
    let window: Vec<_> = rows
        .iter()
        .skip(current_age)
        .take(years as usize + 1)
        .collect();
    let mut sentences = Vec::new();
    for (i, area) in AREAS.iter().enumerate() {
        let Some(best) = window.iter().max_by(|a, b| {
            a.areas[i]
                .partial_cmp(&b.areas[i])
                .unwrap_or(std::cmp::Ordering::Equal)
        }) else {
            continue;
        };
        let Some(worst) = window.iter().min_by(|a, b| {
            a.areas[i]
                .partial_cmp(&b.areas[i])
                .unwrap_or(std::cmp::Ordering::Equal)
        }) else {
            continue;
        };
        sentences.push(s(
            format!(
                "For {}, the strongest year ahead starts at age {} ({}, {} period), the hardest at age {} ({} period).",
                area_words(area.name),
                best.age,
                month_words(best.start),
                graha_words(best.maha),
                worst.age,
                graha_words(worst.maha)
            ),
            vec![format!("best {:.2}, worst {:.2} (Parashari period quality)", best.areas[i], worst.areas[i])],
            0.6,
            vec!["Parashari period quality".to_string()],
        ));
    }
    Section {
        title: format!("The next {years} years"),
        summary: "from the Vimshottari periods".to_string(),
        sentences,
    }
}

/// The whole plain-words reading.
pub fn reading(spk: &Spk, natal: &Chart, at: Instant, ayanamsa: Ayanamsa) -> Vec<Section> {
    let mut out = vec![who(natal), now_section(spk, natal, at, ayanamsa)];
    for area in AREAS.iter() {
        out.push(area_section(natal, *area, at));
    }
    out.push(years_ahead(natal, at, 10));
    out
}

/// Compatibility in words.
pub fn compatibility(
    ash: &Ashtakoota,
    mangal_a: &MangalDosha,
    mangal_b: &MangalDosha,
    syn: &[SynastryAspect],
) -> Vec<Sentence> {
    let mut out = vec![s(
        format!(
            "The Moons score {:.1} of 36 on the eight kutas: {}.",
            ash.total,
            ash.verdict.to_lowercase()
        ),
        ash.kutas
            .iter()
            .map(|k| format!("{} {:.1}/{:.0}: {}", k.name, k.points, k.max, k.detail))
            .collect(),
        0.9,
        vec!["Ashtakoota (Moon nakshatra matching)".to_string()],
    )];
    if ash.nadi_dosha {
        out.push(s(
            "Both Moons share a Nadi. The texts count this the heaviest dosha; some lift it when the Moon signs or lords are the same, which this engine reports but does not assume.".to_string(),
            vec![ash.kutas[7].detail.clone()],
            0.9,
            vec!["Nadi kuta".to_string()],
        ));
    }
    if ash.bhakoot_dosha {
        out.push(s(
            "The Moon signs stand in a 2/12, 5/9 or 6/8 relation (Bhakoot dosha), read as friction in daily living.".to_string(),
            vec![ash.kutas[6].detail.clone()],
            0.8,
            vec!["Bhakoot kuta".to_string()],
        ));
    }
    let md = |m: &MangalDosha, who: &str| -> Sentence {
        if !m.present {
            s(
                format!("{who} has no Mangal dosha."),
                vec![format!(
                    "Mars in house {} from lagna, {} from Moon, {} from Venus",
                    m.from_lagna, m.from_moon, m.from_venus
                )],
                0.95,
                vec!["Mangal dosha".to_string()],
            )
        } else if m.effective {
            s(
                format!("{who} has Mangal dosha with no cancellation in the chart."),
                vec![format!(
                    "Mars in house {} from lagna, {} from Moon, {} from Venus",
                    m.from_lagna, m.from_moon, m.from_venus
                )],
                0.85,
                vec!["Mangal dosha".to_string()],
            )
        } else {
            s(
                format!(
                    "{who} has Mangal dosha by placement, cancelled by: {}.",
                    m.cancellations.join("; ")
                ),
                vec![format!("Mars in house {} from lagna", m.from_lagna)],
                0.7,
                vec!["Mangal dosha".to_string()],
            )
        }
    };
    out.push(md(mangal_a, "The first chart"));
    out.push(md(mangal_b, "The second chart"));
    match (mangal_a.effective, mangal_b.effective) {
        (true, true) => out.push(s("Both carry Mangal dosha; by the usual rule the two cancel each other.".to_string(), vec![], 0.8, vec!["Mangal dosha pairing".to_string()])),
        (true, false) | (false, true) => out.push(s("Only one chart carries an uncancelled Mangal dosha; the texts advise care and remedy before marriage.".to_string(), vec![], 0.7, vec!["Mangal dosha pairing".to_string()])),
        _ => {}
    }
    let harmonious: f64 = syn.iter().filter(|a| a.tone > 0).map(|a| a.weight).sum();
    let tense: f64 = syn.iter().filter(|a| a.tone < 0).map(|a| a.weight).sum();
    if !syn.is_empty() {
        let top: Vec<String> = syn
            .iter()
            .take(6)
            .map(|a| format!("{} {} {} (orb {:.1}°)", a.a, a.aspect, a.b, a.orb))
            .collect();
        out.push(s(
            format!(
                "In Western synastry the harmonious links weigh {:.1} against {:.1} tense; the tightest are {}.",
                harmonious,
                tense,
                top.join(", ")
            ),
            top,
            0.7,
            vec!["Synastry cross-aspects".to_string()],
        ));
    }
    out
}

/// A period in words, for a timeline tile.
pub fn period_words(lord: DashaLord, sub: Option<DashaLord>, quality: f64, area: &str) -> String {
    let tone = if quality >= 0.7 {
        "a strong stretch"
    } else if quality >= 0.5 {
        "a fair stretch"
    } else if quality >= 0.35 {
        "a mixed stretch"
    } else {
        "a testing stretch"
    };
    match sub {
        Some(sl) => format!(
            "{} under {}: {} for {}.",
            capital(graha_words(sl)),
            graha_words(lord),
            tone,
            area_words(area)
        ),
        None => format!(
            "{}: {} for {}.",
            capital(graha_words(lord)),
            tone,
            area_words(area)
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn words_are_formed() {
        assert_eq!(ordinal(1), "1st");
        assert_eq!(ordinal(12), "12th");
        assert_eq!(capital("the sun"), "The sun");
        assert!(
            period_words(DashaLord::Saturn, Some(DashaLord::Venus), 0.8, "Career")
                .contains("strong")
        );
        let u = Utc::new(2027, 3, 12, 0, 0, 0, 0)
            .unwrap()
            .to_instant()
            .unwrap();
        assert_eq!(date_words(u), "12 Mar 2027");
        assert_eq!(month_words(u), "Mar 2027");
    }

    #[test]
    fn compatibility_sentences_cover_every_case() {
        let a = kshana_rules::ashtakoota(45.0, 165.0);
        let md = MangalDosha {
            from_lagna: 7,
            from_moon: 3,
            from_venus: 5,
            present: true,
            from_lagna_present: true,
            cancellations: vec![],
            effective: true,
        };
        let none = MangalDosha {
            from_lagna: 3,
            from_moon: 3,
            from_venus: 5,
            present: false,
            from_lagna_present: false,
            cancellations: vec![],
            effective: false,
        };
        let out = compatibility(&a, &md, &none, &[]);
        assert!(out.len() >= 4);
        assert!(out.iter().all(|x| !x.text.is_empty()));
    }
}

#[cfg(test)]
mod chart_tests {
    use super::*;
    use kshana_chart::{compute, ChartInput};
    use kshana_houses::HouseSystem;
    use kshana_sky::Observer;

    #[test]
    fn reading_has_every_section() {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../data/de421.bsp");
        let Ok(spk) = Spk::open(&p) else { return };
        let birth = Utc::new(1990, 10, 29, 17, 36, 0, 0)
            .unwrap()
            .to_instant()
            .unwrap();
        let ch = compute(
            &spk,
            None,
            &ChartInput {
                instant: birth,
                observer: Observer {
                    latitude_deg: 9.9312,
                    longitude_deg: 76.2673,
                    height_m: 0.0,
                },
                system: HouseSystem::Placidus,
                ayanamsa: Ayanamsa::Lahiri,
                topocentric_moon: false,
            },
        )
        .unwrap();
        let at = Utc::new(2026, 10, 15, 9, 0, 0, 0)
            .unwrap()
            .to_instant()
            .unwrap();
        let r = reading(&spk, &ch, at, Ayanamsa::Lahiri);
        assert_eq!(r.len(), 2 + 8 + 1);
        assert!(r.iter().all(|s| !s.sentences.is_empty()));
        assert!(r[0].sentences.len() >= 4);
        assert!(r[2..10].iter().all(|s| s.sentences.len() >= 3));
    }
}
